const statusBox = document.getElementById("status");
const seedBtn = document.getElementById("seedBtn");

function show(message, type = "info") {
  if (!statusBox) return;
  statusBox.style.display = "block";
  statusBox.style.whiteSpace = "pre-line";
  statusBox.textContent = message;
  statusBox.className = "notice " + type;
}

async function isAdmin(uid) {
  const userRef = doc(db, "users", uid);
  const userSnap = await getDoc(userRef);
  if (!userSnap.exists()) return false;
  return userSnap.data().role === "admin";
}

async function seedKiddiesResources() {
  seedBtn.disabled = true;
  show("Seeding rich Kiddies resources... Please wait.", "info");

  try {
    const batchSize = 450;
    let total = 0;

    for (let i = 0; i < KIDDIES_RESOURCES.length; i += batchSize) {
      const batch = writeBatch(db);
      const chunk = KIDDIES_RESOURCES.slice(i, i + batchSize);

      chunk.forEach((row) => {
        const ref = doc(db, "kiddiesResources", row.id);
        batch.set(ref, {
          ...row,
          status: "active",
          updatedAt: serverTimestamp()
        }, { merge: true });
      });

      await batch.commit();
      total += chunk.length;
    }

    show(`Done. Updated ${total} rich Kiddies resources.\nRefresh kiddies.html and open any resource.`, "success");
  } catch (error) {
    console.error(error);
    show("Failed to seed Kiddies resources. Check console and Firestore rules.\n" + error.message, "error");
  } finally {
    seedBtn.disabled = false;
  }
}

onAuthStateChanged(auth, async (user) => {
  if (!user) {
    show("You must be logged in as admin to seed resources.", "error");
    seedBtn.disabled = true;
    return;
  }

  const admin = await isAdmin(user.uid);
  if (!admin) {
    show("Access denied. Admin role required.", "error");
    seedBtn.disabled = true;
    return;
  }

  show("Admin verified. Click the button to update all Kiddies resources.", "info");
  seedBtn.disabled = false;
});

seedBtn?.addEventListener("click", seedKiddiesResources);
